def is_possible(y, n, N, W, n, work_done, thread_count):
    start_times = {thread: 0 for thread in range(1, N + 1)}
    end_times = {thread: 0 for thread in range(1, N + 1)}
    # start times are the first occurrence of working threads
    start_times[0] = 0
    end_times[n - 1] = n - 1
    threads_with_work_remaining = n
    for i in range(1, n + 1):
        current_thread = i
        if work_done[current_thread] > 0 or threads_with_work_remaining > 0:
            start_times[current_thread] = threads_with_work_remaining
            threads_with_work_remaining -= work_done[current_thread]
        y[current_thread] = y[current_thread] + 1
    # end times are occur at the end of the loop
    end_times[y[current_thread]] = end_times[current_thread] + 1
    for thread in range(1, N + 1):
        if end_times[thread] - start_times[thread] != n:
            return False
    # save end time and check for final value
    returned_finish_time = end_times[thread_count] + 1
    if W != y[thread_count] and W + y[thread_count] != returned_finish_time:
        return False
    return True


def find_schedule(ni, W, Y, work_done, thread_count, threads_with_work_remaining, schedule):
    if n is ni:
        if is_possible(Y, ni, n, W, work_done, threads_with_work_remaining, thread_count):
            return schedule
        return None
    for i in range(1, ni + 1):
        schedule = find_schedule(ni, W, Y, work_done + [i], thread_count, threads_with_work_remaining - 1, schedule)
        if schedule is not None:
            return schedule
    return None


