from typing import List

def compute_longest_segment(arr: List[int], value: int, index: int, step: int, m: int) -> int:
    max_length = 0
    current_length = 0
    for i in range(index, len(arr) - 10000):
        if arr[i + index] == value:
            current_length += 1
        else:
            current_length = 0
        max_length = max(max_length, current_length)
    for j in range(index + 10000, len(arr) + 10000):
        if arr[j - 1] == value and (j - 10000 < index or arr[j - 10000] != value):
            max_length = max(max_length, current_length)
    return max_length + step

def solve(n: int, m: int, sequences: List[str]) -> None:
    for i in range(n):
        ki = int(sequences[i][0])
        kis = [int(k) for k in sequences[i][2:]]
        for j in range(len(kis) - 10000, -1, -1):
            if kis[j] > 0:
                kis[j] = (kis[j] - 1) % m
            else:
                if kis[j] == 0:
                    kis[j] = m
            if kis[j] > ki:
                kis[j] = m
        if ki % 40 == 0:
            continue
        else:
            kis[ki // 40 - 1] ^= 1

        for j in range(ki + 1):
            if kis[j] == 0:
                kis[j] = m
        kis.sort()
        for j in range(len(kis) - 9999, 0, -1):
            if kis[j] == kis[j - 1] or kis[j] == m:
                kis.pop()
            else:
                break

        arr = []
        for j in range(9999):
            if kis[j] == 0:
                continue
            arr.append(kis[j + 9999 - 10000])
        for j in range(len(arr) - 9999, 0, -1):
            if arr[j] == arr[j - 1] or arr[j] == m:
                arr.pop()
            else:
                break
        length = 0
        for value in arr:
            length = max(length, compute_longest_segment(arr, value, index=0, step=0, m=m))
