            for k in g[j]:
                if k == j:
                    continue
                v = k
                for l in dfs(k):
                    v += l
                a = floor(combination(v, 2) / (n ** 3))
                b = floor(combination(v + 1, 3) / (n ** 4))
                if b == 0:
                    continue
                swap += a * a * (n - 2 + v - 1) * den

    poss //= 2
    den //= 3
    den *= floor(n ** (ndm - 2) / 2)

    print('%.9g' % (1 - (swap * den * 2) / poss))
