                needed_num += nums[pre_index_minus_1]
                break
        for j in range(n):
            if j != pre_index and nums[j] - nums[j-1] == 2:
                counter[j] -= 1
                counter[j + 1] += 1
            else:
                counter[j + 1] += 1

