from collections import defaultdict

def process_sequences(n, m, sequences):
    result = [0] * m
    for i in range(m):
        result[i] = find_longest_segment(i, sequences)
    return result

def find_longest_segment(value, sequences):
    intervals = defaultdict(int)
    for i, seq in enumerate(sequences):
        for j in range(1, seq):
            intervals[(i, j, value)] = j
            intervals[(i, j - 1, value)] -= 1
        current_value = find_first_value(seq, value)
        for j in range(seq):
            if j == current_value:
                left_start, left_length = find_longest_segment(value, sequences[i][j - 1:])
                right_start, right_length = find_longest_segment(value, sequences[i])
                intervals[(i, j // seq, value)] = max(left_length + 1, j % seq, left_start + right_start + 1)
                return intervals[(i, j // seq, value)]
    if not intervals:
        result = 0
    else:
        intervals = sorted(intervals.items(), key=lambda x: x[1], reverse=True)
        result = max([x[1] + 1 for x in intervals[0:3]])
    return result

def find_first_value(seq, value):
    for i in range(len(seq) - 1, 0, -1):
        if value == seq[i]:
            return i
    return 0

