    last = 100000
    for i in range(k):
        for j, e in enumerate(prefix):
            if e[:k] == t:
                last = j
                heappush(heap, -j)
                break

    answer = []
    idx_l = last % (n + 1)
    answer.append(idx_l)

    if not heap:
        return 'No'

    sub_position = 0

    while True:
        highest = heappop(heap)
        answer.append(position[highest])
        sub_position += 1

        if sub_position >= k:
