def build_graph(deck, required):
    graph = {}
    for edge in deck:
        if edge in graph:
            graph[edge].append(-edge)
        else:
            graph[edge] = [-edge]
    for edge in required:
        if edge in graph:
            graph[edge].append(-edge)
        else:
            graph[edge] = [-edge]
    return graph

