from collections import deque, defaultdict

def calculate_grundy(n, y, k, x):
    seqs = []
    for i in range(n):
        seq = deque([pow(k, i, y)])
        for j in range(1, n - i):
            seq.append(seq.popleft() * k % y)
        if seq[0] ** 2 % y != i:
            seqs.append(tuple(sorted(seq)))
    g_shift = defaultdict(int)
    g_jump = defaultdict(int)
    for s_key, s_value in seqs:
        g_shift[s_key] = g_jump[s_key % y]
        g_jump[s_key % y] += s_value

    def grundy(val):
        set_ = set([val])
        for times in range(1, y // 2):
            x = times % (y // 2)
            new_set = set()
            for dqr in set_:
