    # Map each ni to its start process index
    for i in range(1, N + 1):
        process_count[i] = i
        start_process[process_count[i]] = i

    # Update the start process indices as ni times they have been executed
    for i, n in enumerate(ni):
        process_count[n] += n

    # Try to map the remaining processes to the needed adjusted indices
    need = set()
    for i in range(1, N + 1):
        if process_count[i] != i and i not in need:
            need.add(process_count[i])
            nei_count = -(-ni // N) # next ni nodes to add, starting from the front
            for j in range(i - 1, -1, -1):
                if process_count[process_count[i]] >= 0 and process_count[process_count[i]] < ni:
                    process_count[j] = process_count[i]
                    break
                if j == 0:
                    break

    # If the topni processes are not all mapped, return "No"
    if process_count[N] != N or process_count[N - 1] < ni - N:
        return "No"

    # Find start process indices to fill up the remaining empty slots
    ret = [-1] * (N * 2)
    process_count[loc := N] = N
    start_process[process_count[loc]] = loc
    for i in range(1, N + 1):
        if i in need:
            need.remove(i)
        if not need:
            break

    loc += 1
    # Locate start multiples of 2*ni in the start list
    start_slot = topni := need.pop()
    for start in range(loc - 1, -1, -2 * ni):
        while -1 < start <= loc:
            if start & 1 == 1: # side slot multiple of 2*ni shift left
                start += (startslot - (start & topni))
            start //= 2
            if not need:
                break
        if start >= loc:
            break
        if process_count[process_count[need[0]]] == -1 or process_count[process_count[need[0]] + 1] < topni:
            continue
        start_process[startslot := process_count[process_count[need[0]] + 1]] = start
        need.remove(nextneed := process_count[end := need[0] + 1])
        start += (startslot + topni) + (1 if len(startslot) else 0)

    top1 := process_count[N - 1]
    startslot := top1 - start_process[loc]
    if startslot == 0:
        if startslot:
            start, ret[start - 1] = 0, 1
        else:
            start, ret[0] = 0, 0
    elif len(leftafterstartslot) == 0:
        for t in range(loc + 1, loc + 2):
            if process_count[start][:t] > 0:
                start += (leftafterstartslot - (0x1) & process_count[start][:t])
                t -= (t & (start - 2))
                break
            if t == loc + 2:
                ret = [*ret, 0]
                continue
        start -= 1
        ret[start] = 1
    else:
        for t in range(0, loc):
            if process_count[start][t + loc * (t // startslot)] > 0:
                start += (start)
                t -= (t & (startslot - 1))
                break
    return start, ret

