import sys

def find_rectangle_coverage(n, m, blue_babies, red_babies):
    blue_baby_to_red_baby = {}
    for i, (x, y) in enumerate(blue_babies, 1):
        for j, (dx, dy) in enumerate(red_babies, 1):
            # Calculate the nearest red baby from the blue baby
            distance = (x - dx) ** 2 + (y - dy) ** 2
            if distance == 0:
                continue
            nearest_red_baby = (i - j) * dx + dy * (n - j)
            blue_baby_to_red_baby[i - j] = nearest_red_baby
        # Sort red babies for each blue baby
        sorted_red_babies = sorted(red_babies)
        for j in range(min(len(nearest_red_baby), len(red_babies))):
            # Calculate the nearest red baby for each guy
            distance = (nearest_red_baby[j] - x) ** 2 + (y - sorted_red_babies[j] - y) ** 2
            nearest_red_baby_sorted = (j + 1) * x - sorted_red_babies[j] * n + (y - sorted_red_babies[j]) * n
            blue_baby_to_red_baby[i - j] = nearest_red_baby_sorted

    # Check for any edge coverage
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0 and blue_baby_to_red_baby[i * j] > 0:  # Top-left corner
                continue
            if blue_baby_to_red_baby[i * j] < 0:  # Any point on the positive x-axis
                continue
            for k in range(n):
                # Check if all sides of a rectangle are covered
                for l in range(m):
                    if i * n + k == j * m + l in blue_baby_to_red_baby:
                        covered_blues = len(blue_baby_to_red_baby[i * n + k])
                        covered_reds = len(blue_baby_to_red_baby[j * m + l])
                        if covered_blues == covered_reds:
                            return i

