import sys

def main():
    n = int(sys.stdin.readline())
    points = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        points.append((x, y))

    memo = set()  # Memoization table for optimal positions of the white token

    def is_win(state):
        x, y = state
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if ny >= 0 and ny < n:
                if (nx, ny) in memo:
                    continue  # Skip already visited states to avoid infinite loop
                memo.add((nx, ny))
                if is_win((nx, ny)):  # If the new state is a win state
                    return True
        return False

    # Check all possible initial positions for the white token
    win_count = 0
    for x, y in points:
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if ny >= 0 and ny < n:
                if (nx, ny) not in memo:
                    memo.add((nx, ny))  # Mark as visited
                    if not is_win((nx, ny)):
                        win_count += 1  # If current state is a winning state for the black player

    print(win_count)

if __name__ == "__main__":
    main()
