import sys
from collections import deque

def play_game(n, nums):
    parity_map = {num % 2: num for num in nums}
    queue = deque(nums)

    while len(queue) > 1:
        oldest_parity = queue.index(queue[0]) % 2
        current_parity = nums[-1] % 2

        for i in range(1, len(queue)):
            if parity_map[queue[i]] % 2 != current_parity:
                if parity_map[current_parity] % 2 != oldest_parity:
                    queue.remove(parity_map[current_parity])
                    parity_map.pop(current_parity)
                else:
                    queue.remove(parity_map[oldest_parity])
                    parity_map.pop(oldest_parity)
                break

        else:
            return -1

    return -sum(parity_map)

