    if W % 2 == 1:
        steps += 1
    return steps * 2 == len(W)

def count_increases(W, ni):
    return W // ni if W % ni == 0 else W // ni + 1, ni // (W % ni - 1) * ni % (W % ni - 1)

def print_schedule(W, ni, schedule):
    print(f"YES\n{' '.join(str(step) for step in schedule)}")

def main():
    N, W = map(int, input().split())
    ni = list(map(int, input().split()))

