    if not is_possible(W):
        return

    # Create a table to count the number of ways to arrange the schedule
    table = [[0 for _ in range(W + 1)] for _ in range(2)]

    # Initialize the table for the first process grouping
    for i in range(1, W + 1):
        if i % ni[0] == 0:
            table[0][i] = ni[0] // (i // ni[0] - 1) * ni[0] % (i // ni[0] - 1)
            table[1][i] = ni[0] - table[1][i]
        else:
            table[0][i] = 0
            table[1][i] = ni[0]

    # Build the table for the rest of the processes
    for i in range(2, N):
        step_count, process_steps = count_increases(W, ni[i])
        new_table = [[0 for _ in range(W + 1)] for _ in range(2)]
        for s in table[1]:
            for w in range(step_count, W + 1):
                new_table[0][w] += table[0][s] * (w // s)
                new_table[1][w] += table[1][s] * (w // s)
            for w in range(step_count + 1, process_steps + 1):
                new_table[1][w] += s * (w // s)
        table = new_table
        # Update partition sums for all remaining steps in the update table
        for s in table[0]:
            for ws in range(w, step_count - 1, -1):
                table[0][ws] += table[0][w] * (ws // w)
                table[1][ws] += table[1][w] * (ws // w)

