from collections import deque

def find_sum(arr, l, r):
    return sum(arr[i] for i in range(l, r))

def play_game(nums):
    n = len(nums)
    ans = deque(maxlen=n)

    # Sort the array
    nums.sort()

    a = b = nums[0]

    # First move
    ans.append(a)
    a += 1

    for i in range(n):
        val = nums[i]
        if i % 2 == 0:
            ans.clear()
            for j in range(n):
                if val % 2 != nums[j] % 2 and j <= i:
                    ans.append(nums[j])
                    b = val + nums[j]
                    break
                elif j >= n:
                    break
        else:
            if a == val:
                continue
            ans.clear()
            for j in range(n):
                if val % 2 != nums[j] % 2 and j <= i:
                    ans.append(nums[j])
                    break
            b = val + nums[j]

        if ans[-1] == min(ans):
            a += 1

    sum_diff = find_sum(ans, 0, len(ans)) - find_sum(ans, 0, len(ans) // 2)
    return sum_diff

