def count_win_positions(depth, points, memo):
    # Check if a move is a win for the white player
    def is_win(x, y, i):
        count = defaultdict(int)
        for p in points:
            kx = (x + p[0]) // 2
            ky = (y + p[1]) // 2
            if abs(kx - x) + abs(ky - y) <= depth:
                count[(abs(kx - x), abs(ky - y))] = 1
            if (x, y) in points and kx == x and ky == y:
                count[0] = 1
        return sum(count.values()) == 1

    # Memoized function to get the number of win positions
    @lru_cache(None)
    def dfs(x, y, d, res):
        if x < -100 or x > 100 or y < -100 or y > 100:
            return
        if d == 0:
            for dx in [1, -1]:
                res += is_win(x + dx, y, d)
        elif d == 2:
            for dy in [1, -1]:
                res += is_win(x, y + dy, d)
        elif d == 4:
            for dx, dy in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
                my_res = dfs(x + dx, y + dy, d - 1, 0)
                if my_res == 1:
                    res += my_res
        elif d == 8:
            for dx, dy in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
                my_res = dfs(x + dx, y + dy, d - 1, 1)
                res += my_res
        return res  # memoized

    return sum(dfs(x, y, depth, 0) for x, y in points) + is_win(0, 0, depth)

