import itertools

def find_schedule(ni, W):
    results = []

    for permutation in itertools.permutations(range(1, W // sum(ni) + 1), sum(ni)):
        steps = [(i, 0) for i in range(1, sum(ni) + 1)]

        for step, process_id in enumerate(permutation):
            for repeat_count in ni[process_id-1]:
                steps[step + repeat_count - 1] = (steps[step + repeat_count - 1][0],
                                                   "update")
                steps[step + repeat_count] = (steps[step + repeat_count][0],
                                              process_id + 1)

        y = 0
        for i in range(len(steps)):
            if steps[i][1] == "update":
                if i != 0:
                    yi, y = steps[i-1][1], y
                    for _ in range(ni[i-1]):
                        yi += 1
                steps[i] = (steps[i][0], "finish")

        if y == W:
            results.append([result[0] + result[1] for result in steps if result[0] != 'finish'][:ni])

    return results

