from collections import *

def kitten_game(n, m, x, y, max_pairs, min_pairs):
    min_heap = heapq.nsmallest(n, min_pairs, key=lambda pair: pair[1])
    max_heap = heapq.nsmallest(m, max_pairs, key=lambda pair: pair[0])

    moves = []
    prev_min, _ = min_heap[0]

    try:
        while x >= 0 or y >= 0:
            next_move = float("inf")
            for pair in min_heap:
                if pair[0] + prev_min <= x and pair[1] + prev_min <= y:
                    next_move = min(pair[0], pair[1]) 
                    break
            if next_move > 0.0 and next_move < 1.0:
                prev_min += int(order_operator(next_move)[4:-1])
                x -= int(order_operator(next_move)[4:-1])
                y -= int(order_operator(next_move)[4:-1])
            elif next_move == 0:
                return "Max"

            for pair in max_heap:
                pair[0] -= prev_min
                pair[1] -= prev_min
                if pair[0] <= 0 and pair[1] <= 0:
                    return "Min"
                if len(moves) < m or pair[1] != moves[m-1][1]:
                    moves.append((pair[0], pair[1]))
            min_heap = sort_min_heap(min_heap, x, y)
        return "Min"

    except IndexError:
        return min_heap[0][1] + (y if y < 0 else 0) / (x if x < 0 else 1)
    except ValueError:
        return "Max"

