from math import gcd
from collections import defaultdict
from itertools import combinations

def multiple(n, a, b):
    mm1 = (gcd(n, a), gcd(n, b))
    for div1, div2 in combinations(range(1, mm1[0] * mm1[1] // a), 2):
        if div1 * a + div2 * b > max(mm1[0], mm1[1]) or (mm1[0] // div1 * (div2 + 1) % mm1[1] - div2) % div1 > 1:
            continue
        if n * div1 != (div1 + div2) * (n // div2):
            continue
        if n % div1 == 1:
            return div1
    return -1

def find_min_mem_limit():
    prod = 1
    job_categories = defaultdict(int)
    category_count = defaultdict(int)
    for char in s:
        if char in job_categories:
            continue
        categories = set(seq + [char] for seq in combinations(range(1, n + 1), min(a, max(s.count(char) for char in job_categories) + len(s.split(char)))))
        for cnt in sorted(category_count[cat] for cat in categories if len(cat) % a == 0):
            prod *= cnt
            if cnt * a < len(categories):
                return
    try:
        mem_limit = prod // multiple(prod, a, b) // multiple(prod, b, a)
    except:
        mem_limit = -1
    return mem_limit

