from collections import defaultdict

def find_parent(parent, x):
    if parent[x] != x:
        parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union_parent(parent, a, b):
    a = find_parent(parent, a)
    b = find_parent(parent, b)
    if a < b:
        parent[b] = a
    else:
        parent[a] = b

def dfs(node, prev, parent, include_first, include_second):
    visited[node] = 1
    if include_first:
        answer += parent[node]
    if include_second:
        answer += parent[node] * pow(*current_sequence, 3)
    for next_node in tree[node]:
        if visited[next_node] == 0:
            current_sequence.append(next_node)
            dfs(next_node, node, parent, include_first, include_second)
            current_sequence.pop()
    parent[node] = node

def main():
    n, y, k, num = map(int, input().split())
    values = list(map(int, input().split()))
    tree = defaultdict(list)
    for _ in range(n - 1):
        start, end = map(int, input().split())
        tree[start].append(end)
        tree[end].append(start)

    current_sequence = [0]
    visited = [0] + [0 for _ in range(num - 1)]
    parent = [i for i in range(num)]
    start_node = 0
    answer = 0
    current_grade = 0
    current_log = 0

    for i in range(n):
        if i == 0 and k != 0:
            answer = 1
            current_grade = current_log = 1
            dfs(i + 1, i + 1, parent, i > 0 and k > 0, i > 0 and k != 0)
        elif i == 0:
            current_grade = pow(current_log, k)
        for j in range(len(tree[i])):
            next_node = tree[i][j]
            current_grade *= current_log
            current_grade += values[next_node]
            current_log *= k
            dfs(next_node, i + 1, parent, True, False)

    for j in range(1, num):
        start_node = j
        if k == 0:
            include_first = include_second = False
        else:
            include_first = include_second = True
        answer += dfs(start_node, start_node, parent, include_first, include_second) / num ** 2
    print(int(answer))

if __name__ == "__main__":
