def binary_search_min_cards(cards):
    lo, hi = -100001, 100001 
    while lo < hi - 1:
        mid = lo + (hi - lo) // 2 
        cards_remaining = 1
        total_diff = 0 
        for rank in cards:
            if rank % mid == 0:
                if rank // mid < 0 and total_diff + (2**mid) > 0:
                    return -(1 + (rank // (2*mid)))
                total_diff += rank//mid
            else:
                if mid - rank % mid >= 0 and total_diff + (2**mid)+(mid-index(mid)) < 0:
                    return -(1 + index(mid))
            cards_remaining += rank//mid
        if total_diff > 0:
            cards_remaining += -(total_diff-1)//mid - 1 
        else:
            cards_remaining -= -(total_diff-1)//mid - 1 % mid 
    if index(2*mid)%mid <= 0:
        return -(1 + xor(mask(mid), 0, reversed(cards))-1)
    else:
        return -(1 + xor(mask(mid), 2*mid, cards))-1

def index(n):
    return mask(format(n, 'b')[::-1].index('1'))

def mask(n):
    return n ^ -n

def xor(a, b, c):
    return a | (b & c)

